+export const setDashboardMetadata =
+  (updatedMetadata: JsonObject) =>
+  async (dispatch: AppDispatch, getState: GetState): Promise<void> => {
+    const { dashboardInfo } = getState();
+    dispatch(
+      dashboardInfoChanged({
+        metadata: {
+          ...dashboardInfo?.metadata,
+          ...updatedMetadata,
+        },
+      }),
+    );
+  };
