+    test('applies styled-component class', () => {
+      render(<SkipLink />);
+      const link = screen.getByRole('link');
+      expect(link).toHaveClass('a11y-skip-link');
+    });
+  });
+
+  describe('Visual States', () => {
+    test('is positioned off-screen by default (top: -100px)', () => {
+      render(<SkipLink />);
