+      formData,
+      resultFormat,
+      resultType,
+      force,
+      method,
+      querySettings,
+      parseMethod,
+    );
+  }
+  return v1ChartDataRequest(
+    formData,
+    resultFormat,
+    resultType,
+    force,
+    querySettings,
+    setDataMask,
+    ownState,
+    parseMethod,
+  );
+}
