+    resetTranslation();
+    // After reset, calling t() should warn again
+    t('hello');
+    expect(consoleSpy).toHaveBeenCalledWith(
+      'You should call configure(...) before calling other methods',
+    );
+    consoleSpy.mockRestore();
+  });
