body:
**Suggestion:** The copy-status timeout is never cleared, so closing the modal before the timer fires can trigger a state update after unmount, and repeated clicks can race with older timers that reset the copied state too early. Store the timeout id in a ref, clear any existing timer before creating a new one, and clean it up on unmount. [resource leak]

<details>
<summary><b>Severity Level:</b> Major ⚠️</summary>

```mdx
- ⚠️ API key modal copy feedback can reset unpredictably.
- ⚠️ Timer callback runs after modal unmount lifecycle.
- ⚠️ Affects UserInfo API Keys panel interaction flow.
```
</details>

```suggestion
import { useEffect, useRef, useState } from 'react';
import { SupersetClient } from '@superset-ui/core';
import { t } from '@apache-superset/core/translation';
import { css, useTheme } from '@apache-superset/core/theme';
import { Alert } from '@apache-superset/core/components';
import {
  FormModal,
  FormItem,
  Input,
  Button,
  Modal,
} from '@superset-ui/core/components';
import { useToasts } from 'src/components/MessageToasts/withToasts';

interface ApiKeyCreateModalProps {
  show: boolean;
  onHide: () => void;
  onSuccess: () => void;
}

interface FormValues {
  name: string;
}

export function ApiKeyCreateModal({
  show,
  onHide,
  onSuccess,
}: ApiKeyCreateModalProps) {
  const theme = useTheme();
  const { addDangerToast, addSuccessToast } = useToasts();
  const [createdKey, setCreatedKey] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const copiedResetTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    () => {
      if (copiedResetTimeoutRef.current) {
        clearTimeout(copiedResetTimeoutRef.current);
      }
    };
  }, []);

  const handleFormSubmit = async (values: FormValues) => {
    try {
      const response = await SupersetClient.post({
        endpoint: '/api/v1/security/api_keys/',
        jsonPayload: values,
      });
      const key = response.json?.result?.key;
      if (!key) {
        throw new Error('API response did not include a key');
      }
      setCreatedKey(key);
      addSuccessToast(t('API key created successfully'));
    } catch (error) {
      addDangerToast(t('Failed to create API key'));
      throw error;
    }
  };

  const handleCopyKey = async () => {
    if (!createdKey) {
      return;
    }
    try {
      await navigator.clipboard.writeText(createdKey);
      setCopied(true);
      if (copiedResetTimeoutRef.current) {
        clearTimeout(copiedResetTimeoutRef.current);
      }
      copiedResetTimeoutRef.current = setTimeout(() => setCopied(false), 2000);
```
