+export interface FilterState {
+  originalFilterModel: AgGridFilterModel;
+  simpleFilters: SQLAlchemyFilter[];
+  complexWhere?: string;
+  havingClause?: string;
+  lastFilteredColumn?: string;
+  inputPosition?: FilterInputPosition;
